class Checker:
    def isValidSudoku(self, board, result):
        rows = [set() for _ in range(9)]
        cols = [set() for _ in range(9)]
        boxes = [set() for _ in range(9)]
        expected = True
        for i in range(9):
            if len(board[i]) != 9:
                return False
            for j in range(9):
                cell = board[i][j]
                if cell == ".":
                    continue
                if not isinstance(cell, str) or len(cell) != 1 or cell < "1" or cell > "9":
                    return False
                box = (i // 3) * 3 + (j // 3)
                if cell in rows[i] or cell in cols[j] or cell in boxes[box]:
                    expected = False
                    break
                rows[i].add(cell)
                cols[j].add(cell)
                boxes[box].add(cell)
            if not expected:
                break
        return result == expected

